{"id": "temporal-01", "type": "temporal", "question": "Teacher got a Residency License in 2017 under the older rules and is now in year 8 of renewal. Which requirements apply to them: the ones in effect when the RL was issued, or the current ones?", "license_types": ["Residency License", "Initial Professional License"], "facts_given": ["RL issued 2017", "current year 2025", "in year 8 of renewal"], "missing_fact": null, "notes": "Tests whether the assistant separates grandfathering from current requirements and admits uncertainty about transition rules."}
{"id": "temporal-02", "type": "temporal", "question": "Initial Professional License expired in 2019. Applicant wants reinstatement in 2025. Which reinstatement rules apply and does the length of the lapse change anything?", "license_types": ["Initial Professional License", "reinstatement"], "facts_given": ["IPL expired 2019", "reinstatement sought 2025", "no renewal credits completed since expiration"], "missing_fact": null, "notes": "Lapse duration plus a rule change between 2019 and 2025."}
{"id": "temporal-03", "type": "temporal", "question": "Master's in school administration finished 2014 at a program that's since been reviewed. Applying for an admin license now. Does the completion date or the program's approval status at the time matter?", "license_types": ["administrator license"], "facts_given": ["master's completed 2014", "applying 2025", "program later reviewed"], "missing_fact": null, "notes": "Degree date versus program approval status at completion."}
{"id": "temporal-04", "type": "temporal", "question": "Praxis content test passed in 2010, now applying for a Continuing Professional License. Does a test score age out or does it still count?", "license_types": ["Continuing Professional License"], "facts_given": ["content test passed 2010", "applying now (2025)", "no other testing on file"], "notes": "Score validity period is time-dependent."}
{"id": "temporal-05", "type": "temporal", "question": "out of state license GA issued 2008, expired 2016. applying NC 2024. which rules govern?", "license_types": ["out-of-state license reciprocity"], "facts_given": ["GA license issued 2008", "GA license expired 2016", "applying 2024"], "missing_fact": null, "notes": "Terse. Expiration before application date is the key temporal wrinkle."}
{"id": "temporal-06", "type": "temporal", "question": "Teacher's renewal cycle closed June 30. Some CEUs were completed in July and August after the cycle ended. Which cycle do those count toward?", "license_types": ["Continuing Professional License"], "facts_given": ["cycle ended June 30", "CEUs completed July and August", "CPL holder"], "missing_fact": null, "notes": "Boundary dates for renewal cycles."}
{"id": "temporal-07", "type": "temporal", "question": "Was there any temporary or pandemic-era flexibility in NC licensure between 2020 and 2022 that changed how renewal credits or license extensions were handled? Teacher's license was due during that window.", "license_types": ["Continuing Professional License", "Initial Professional License"], "facts_given": ["license due date fell in 2020–2022", "teacher's renewal affected by that window"], "missing_fact": null, "notes": "Asks about a possible temporary policy, so the assistant should not assume one existed."}
{"id": "temporal-08", "type": "temporal", "question": "Birth through kindergarten program started 2021, finished 2023. Does the program need to meet the standards in effect when they enrolled or when they finished?", "license_types": ["Birth through Kindergarten license area"], "facts_given": ["program start 2021", "program finish 2023", "candidate is seeking the BK license area"], "missing_fact": null, "notes": "Enrollment date versus completion date. Assistant should check whether the answer is stated anywhere in the policies."}
{"id": "temporal-09", "type": "temporal", "question": "National Board certification earned 2012. Teacher now renewing a CPL in 2025. Does NBC status count the same way under today's renewal rules as it did when it was earned?", "license_types": ["Continuing Professional License", "National Board certification"], "facts_given": ["NBC earned 2012", "renewing 2025", "holds CPL"], "missing_fact": null, "notes": "NBC credit validity and renewal treatment across rule changes."}
{"id": "temporal-10", "type": "temporal", "question": "CTE teacher's industry credential from 2016 may be past its validity window. Teacher is applying for a license in 2025. Does the credential's issue date still count?", "license_types": ["Career and Technical Education license", "Permit to Teach"], "facts_given": ["industry credential issued 2016", "applying 2025", "CTE teaching area"], "missing_fact": null, "notes": "Credential age limits versus issue date."}
